"""RV research pages: complete media, transparent figures and relevant next steps."""
from urllib.parse import quote
import re
import site_templates as t
E=t.E

def payment(price,down=.2,apr=9.99,months=240):
    r=apr/1200
    return round(price*(1-down)*r/(1-(1+r)**-months)) if price else 0

def similar_units(unit,units):
    pool=[x for x in units if x['stock']!=unit['stock'] and x['type']==unit['type'] and x['status']=='listed']
    def score(x):
        return (x['condition']!=unit['condition'], x['model'].lower()!=unit['model'].lower(), x['brand']!=unit['brand'],
                abs((x.get('length') or unit.get('length') or 0)-(unit.get('length') or 0))*2+abs((x['price'] or 0)-(unit['price'] or 0))/10000, not x['image'])
    return sorted(pool,key=score)[:6]

def description_html(unit):
    blocks=unit.get('descriptionSections') or [{'kind':'paragraph','text':p} for p in re.split(r'(?<=\.)\s+(?=[A-Z])',unit.get('description','')) if p]
    result=[];in_list=False
    for b in blocks:
        if b['kind']=='item':
            if not in_list:result.append('<ul>');in_list=True
            result.append('<li>'+E(b['text'])+'</li>')
        else:
            if in_list:result.append('</ul>');in_list=False
            tag='h3' if b['kind']=='heading' else 'p'
            result.append(f'<{tag}>{E(b["text"])}</{tag}>')
    if in_list:result.append('</ul>')
    return ''.join(result) or '<p>Ask us for the equipment and condition details for this stock number.</p>'

def benefits():
    return '''<div class="purchase-benefits"><div><b>No freight or prep fees</b><p>More clarity in your written purchase quote.</p></div><div><b>A personal RV orientation</b><p>Get familiar with your RV’s systems with a technician.</p></div><div><b>Time to settle in</b><p>Ask about staying in the Texas onsite delivery campground.</p></div><div><b>Help with your arrival</b><p>Arrange local airport pickup with your sales associate for delivery.</p></div></div><p class="data-note">Coordinate location-specific arrangements and your delivery inspection with your specialist before traveling.</p>'''

def detail(u,all_units,config):
    name=t.title(u);stock=E(u['stock']);archived=u['status']=='unavailable';price=u.get('price')
    canonical=config['origin'].rstrip('/')+'/units/'+quote(u['stock'],safe='')+'.html'
    label='Last listed price' if archived else 'Listed price'
    sms='sms:8177907771?body='+quote(f'Hi MHSRV, I’m interested in {name}, stock #{u["stock"]}. Please confirm availability and help with my questions.')
    docsms='sms:8177907771?body='+quote(f'Please send the floorplan, brochure and installed options for {name}, stock #{u["stock"]}.')
    photos=u.get('photos',[])
    slides=''.join(f'<figure class="inline-slide"><button data-photo="{i}" aria-label="Enlarge photo {i+1}"><img src="{E(p)}" alt="{E(name)} — photo {i+1}" width="1200" height="800" {"fetchpriority=high" if i==0 else "loading=lazy"} decoding="async" draggable="false"></button></figure>' for i,p in enumerate(photos))
    thumbs=''.join(f'<button class="inline-thumb" data-inline-photo="{i}" aria-label="Show photo {i+1}" aria-current="{str(i==0).lower()}"><img src="{E(p.replace("width=1200;quality=75","width=160;quality=60"))}" alt="" width="120" height="80" loading="lazy" draggable="false"></button>' for i,p in enumerate(photos))
    gallery=f'''<section class="inline-gallery" aria-label="RV photo gallery"><div class="inline-photo-track" id="inlinePhotoTrack" tabindex="0" aria-label="Swipe, scroll or use arrow keys to browse all {len(photos)} photos">{slides}</div><div class="inline-gallery-toolbar"><div><button class="icon-button" data-inline-step="-1" aria-label="Previous photo">←</button><span id="inlinePhotoCount" aria-live="polite">1 / {len(photos)}</span><button class="icon-button" data-inline-step="1" aria-label="Next photo">→</button></div><span class="muted">Swipe to explore · Tap to enlarge</span><button class="text-link" data-photo="0">{t.icon('camera')} Full screen</button></div><div class="inline-thumbnails" aria-label="All listing photos">{thumbs}</div></section>''' if photos else '<div class="photo-placeholder detail-empty-photo">Photos are coming. Request a personal walk-through below.</div>'
    quick=[('Length',f'{u["length"]} ft' if u.get('length') else 'Not listed'),('Sleeps',u.get('sleeps') or 'Not listed'),('Slideouts',u.get('slides') if u.get('slides') is not None else 'Not listed'),('Fuel',u.get('fuel') if u.get('fuel') not in ('','n/a') else 'Not listed')]
    quick_html=''.join(f'<div class="quick-spec"><small>{k}</small><strong>{E(v)}</strong></div>' for k,v in quick)
    pricing=''
    if price and u.get('msrp') and u['msrp']>price:
        savings=u['msrp']-price
        pricing+=f'<div class="msrp">MSRP <s>{t.money(u["msrp"])}</s></div><div class="save-amount">{t.money(savings)} below MSRP · {savings/u["msrp"]:.0%}</div>'
    if price and u.get('regularPrice') and u['regularPrice']>price:
        pricing+=f'<p class="regular-price">Regular advertised price <s>{t.money(u["regularPrice"])}</s><br>{(u["regularPrice"]-price)/u["regularPrice"]:.0%} below regular advertised price</p>'
    if price:
        pricing+=f'<a href="#payment" class="price-payment">Est. <strong id="pricePayment">${payment(price):,}/mo</strong> {t.icon("arrow")}</a><p class="data-note price-assumptions" id="priceAssumptions">20% down · 9.99% illustrative APR · 240 months. Taxes and fees excluded. Adjust below.</p>'
    fp=f'<button class="floorplan-image" data-floorplan aria-label="Enlarge floorplan"><img data-document-image src="{E(u["floorplanImage"])}" alt="{E(name)} floorplan" loading="lazy" width="1100" height="520"></button>' if u.get('floorplanImage') else '<p>The exact floorplan is not attached yet. Ask us for a copy.</p>'
    bc=u.get('dealerListingUrl','')
    if bc:fp+=f'<a class="text-link" href="{E(bc)}#section-detail-floorplan-anchor" target="_blank" rel="noopener">Check the Blue Compass floorplan {t.icon("arrow")}</a>'
    fp+=f'<p class="document-request-links"><button class="text-link" data-lead="Request the exact floorplan" data-stock="{stock}">Request the exact layout</button><a href="{E(docsms)}">Text for documents {t.icon("message")}</a></p>'
    b=u.get('brochure')
    brochure=f'<button class="document-card" data-brochure>{t.icon("book")}<span><b>{E(b["label"])}</b><small>{"Matching model year" if b["sameYear"] else "Reference brochure · verify model year"} · Read PDF here</small></span></button><a class="text-link" target="_blank" rel="noopener" href="{E(b["url"])}">Download source PDF {t.icon("arrow")}</a>' if b else f'<button class="document-card" data-lead="Request the factory brochure" data-stock="{stock}">{t.icon("book")}<span><b>Factory brochure</b><small>Request the right model year and floorplan.</small></span></button>'
    if not b and bc:brochure+=f'<a class="text-link" href="{E(bc)}" target="_blank" rel="noopener">Check documents at Blue Compass {t.icon("arrow")}</a>'
    video=f'<div class="inline-video" id="inlineVideo"><button class="video-button" data-inline-video="{E(u["video"])}" aria-label="Play related model video on this page"><img src="https://i.ytimg.com/vi/{E(u["video"])}/hqdefault.jpg" alt="Related RV model video" loading="lazy" width="640" height="360"><span class="play-icon">{t.icon("play")}</span></button></div><p class="data-note">Related model video. Model year, floorplan and installed equipment may differ from this stock.</p>' if u.get('video') else '<p>No video is mapped to this stock yet. Explore related tours or ask for your own walk-through.</p>'
    yt=u.get('youtubeSearchUrl') or 'https://www.youtube.com/@motorhomespecialist/search?query='+quote(name)
    video+=f'<div class="resource-actions"><a class="button outline small" href="{E(yt)}" target="_blank" rel="noopener">Search MHSRV’s model videos {t.icon("play")}</a><button class="text-link" data-lead="Request a personal video walk-through" data-stock="{stock}">Request a personal walk-through</button></div>'
    if u.get('tour'):video+='<button class="button outline small" data-tour>Explore the listed 360° tour</button>'
    payment_html=f'''<section class="detail-section" id="payment"><p class="eyebrow">Make the numbers your own</p><h2>Build your payment estimate.</h2><div class="down-slider"><label for="calcDownPercent">Down payment <strong id="downPercentLabel">20%</strong></label><input type="range" id="calcDownPercent" min="0" max="100" step="1" value="20"></div><div class="payment-inputs"><div class="field"><label for="calcDown">Down payment ($)</label><input id="calcDown" type="number" inputmode="decimal" min="0" max="{price}" value="{round(price*.2)}"></div><div class="field"><label for="calcApr">Illustrative APR (%)</label><input id="calcApr" type="number" inputmode="decimal" min="0" max="36" step=".01" value="9.99"></div><div class="field"><label for="calcTerm">Loan term</label><select id="calcTerm"><option value="60">5 years</option><option value="120">10 years</option><option value="180">15 years</option><option value="240" selected>20 years</option></select></div></div><label class="term-guide"><input type="checkbox" id="calcTermGuide"> Use conservative term guidance based on amount financed</label><p class="data-note" id="calcTermNote">Optional planning guide: up to 10 years at $20,000 or less financed, 15 years through $50,000, and 20 years above $50,000. These are planning assumptions, not lender eligibility rules.</p><div class="payment-result"><span>Estimated payment</span><strong id="calcResult" aria-live="polite">${payment(price):,}/mo</strong></div><p class="data-note" id="calcTotals"></p><p class="data-note">Illustration only, not a financing offer. Taxes, title, registration, fees and insurance are excluded. APR and terms are examples; actual financing depends on lender approval, the RV and your circumstances.</p><a class="button outline small" id="detailFinanceLink" href="../get-prequalified.html?stock={quote(u['stock'])}">Discuss these numbers {t.icon('arrow')}</a></section>''' if price else ''
    rows=''.join(f'<tr><th scope="row">{E(k)}</th><td>{E(v)}</td></tr>' for k,v in u.get('specs',{}).items())
    fees=f'''<details class="fee-panel"><summary>See the price breakdown {t.icon('chevron')}</summary><dl><div><dt>{label}</dt><dd>{t.money(price)}</dd></div><div><dt>Freight</dt><dd>$0</dd></div><div><dt>Vehicle preparation</dt><dd>$0</dd></div><div><dt>Documentation</dt><dd>{'$225' if u['state']=='TX' else 'Confirm with location'}</dd></div><div><dt>Taxes, title &amp; registration</dt><dd>Based on registration</dd></div><div><dt>Other charges / selected products</dt><dd>Itemized in your quote</dd></div></dl><p class="data-note">{'Texas documentation amount is based on MHSRV’s published pricing.' if u['state']=='TX' else 'Documentation requirements vary by location.'} Ask for the written total for this stock number and your registration address.</p><button class="text-link" data-lead="Request an itemized out-the-door quote" data-stock="{stock}">Get my complete written quote {t.icon('arrow')}</button></details>'''
    availability=(f'No longer in the feed as of {E(u.get("unavailableSince",config["inventoryDate"]))}. Last listing details: {E(u["updated"])}.' if archived else f'Inventory snapshot: {E(u["updated"])}. Confirm current price and availability with your specialist.')
    content=f'''<main id="main" class="container" data-detail="{stock}" data-detail-v2><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="../index.html#inventory">Shop RVs</a><span>/</span><a href="../{t.TYPE_PATHS[u['type']]}/">{t.TYPE_NAMES[u['type']]}</a><span>/</span><span>#{stock}</span></nav><div class="detail-title-row"><div><p class="eyebrow">{E(u['condition'])} · {t.TYPE_NAMES[u['type']]}</p><h1>{E(name)}</h1><p><span>{t.icon('pin')} {E(u['city'])}, {E(u['state'])}</span><span>Stock #{stock}</span><span>{t.STATUS[u['status']]}</span>{'<span class="arrival-detail">Just arrived</span>' if u.get('newArrival') and not archived else ''}</p></div><div class="detail-actions"><button class="button outline small" data-save="{stock}" aria-pressed="false" aria-label="Save this RV">{t.icon('heart')} Save</button><button class="button outline small" data-share>{t.icon('share')} Share</button></div></div>{gallery}<div class="detail-layout"><div class="detail-main"><nav class="detail-nav" aria-label="RV details"><a href="#overview">Overview</a><a href="#floorplan">Floorplan</a><a href="#specs">Specs</a><a href="#video">Video</a>{'<a href="#payment">Payment</a>' if price else ''}</nav><section class="detail-section" id="overview"><h2>The details that matter.</h2><div class="quick-specs">{quick_html}</div><p class="data-note">From the dealer inventory export, updated {E(u['updated'])}. Missing values are not estimated.</p><div class="inline-concierge"><div><h3>A question before you go further?</h3><p>Explore the listing or get the exact answer from a specialist.</p></div><button class="button outline small" data-assistant>{t.icon('spark')} Ask about this RV</button></div><div class="feature-chips">{''.join('<span>'+E(f)+'</span>' for f in u['features'])}</div></section><section class="detail-section" id="floorplan"><details class="research-section" open><summary><h2>Floorplan &amp; documents</h2></summary>{fp}<p class="data-note">Manufacturer layouts and brochures may show optional equipment. Verify the exact unit.</p><div class="documents-grid">{brochure}<button class="document-card" data-lead="Request the window sticker and installed options" data-stock="{stock}">{t.icon('file')}<span><b>Window sticker &amp; options</b><small>Request this stock’s equipment list.</small></span></button></div></details></section><section class="detail-section"><details class="research-section" open><summary><h2>About this RV</h2></summary><div class="description-text rich-description">{description_html(u)}</div></details></section><section class="detail-section" id="specs"><details class="research-section" open><summary><h2>Specifications</h2></summary><table class="spec-table"><tbody>{rows}</tbody></table><p class="data-note">Confirm weights, capacities, dimensions and installed equipment on the actual RV. Tow-vehicle compatibility requires a separate review.</p><button class="text-link" data-lead="Confirm missing specifications" data-stock="{stock}">Ask about a missing specification {t.icon('arrow')}</button></details></section><section class="detail-section" id="video"><h2>Walk through the possibilities.</h2>{video}</section>{payment_html}<section class="detail-section"><h2>More support for your first miles.</h2>{benefits()}<button class="text-link" data-lead="Plan delivery and purchase benefits" data-stock="{stock}">Plan my delivery {t.icon('arrow')}</button></section><section class="detail-section"><h2>The experience, in their words.</h2><p>Explore real dealership stories from past MHSRV customers.</p><a href="../reviews.html?brand={quote(u['brand'])}" class="text-link">Read {E(u['brand'])} customer stories {t.icon('arrow')}</a></section></div><aside class="price-panel"><div class="price-panel-main"><p class="price-label">{label}</p><div class="listed-price">{t.money(price)}</div>{pricing}{fees}<button class="button yellow" data-lead="{'Find a similar available RV' if archived else 'Confirm price and availability'}" data-stock="{stock}">{'Find a similar RV' if archived else 'Confirm availability'} {t.icon('arrow')}</button><a class="button outline" href="{E(sms)}">{t.icon('message')} Text about this RV</a><button class="text-link" data-lead="Request a personal video walk-through" data-stock="{stock}">Request a personal walk-through</button><div class="availability"><b>{t.STATUS[u['status']]}</b>{availability}</div><label class="compare-check"><input type="checkbox" data-compare="{stock}"> Add to comparison</label></div><div class="price-panel-footer">Your specialist is a call away.<a href="tel:{u['phone']}">{t.icon('phone')} {u['phone'][:3]}-{u['phone'][3:6]}-{u['phone'][6:]}</a></div></aside></div><section class="learn-section" style="padding-top:0"><div class="section-heading"><div><p class="eyebrow">Keep exploring</p><h2>Similar RVs, worth a closer look.</h2></div><a class="text-link" href="../{t.TYPE_PATHS[u['type']]}/">View more {t.icon('arrow')}</a></div><div class="result-grid">{''.join(t.card(x,'../') for x in similar_units(u,all_units))}</div></section><script id="unitData" type="application/json">{t.J(u)}</script></main><div class="detail-mobile-cta"><div><small>{label}</small><strong>{t.money(price)}</strong></div><a class="button outline small" href="tel:{u['phone']}" aria-label="Call about this RV">{t.icon('phone')} Call</a><a class="button outline small" href="{E(sms)}" aria-label="Text about this RV">{t.icon('message')} Text</a><button class="button yellow small" data-lead="Confirm price and availability" data-stock="{stock}">Ask us</button></div>'''
    product={'@context':'https://schema.org','@type':'Product','@id':canonical+'#rv','name':name,'sku':u['stock'],'url':canonical,'brand':{'@type':'Brand','name':u['brand']},'category':t.TYPE_NAMES[u['type']],'description':u.get('description','')[:350],'additionalProperty':[{'@type':'PropertyValue','name':k,'value':v} for k,v in u['specs'].items()]}
    if u.get('image'):product['image']=[u['image']]
    if config['mode']=='production' and price and u['status'] not in ('pending','unavailable'):
        product['offers']={'@type':'Offer','price':price,'priceCurrency':'USD','url':canonical,'availability':'https://schema.org/'+('PreOrder' if u['status'] in ('onorder','coming') else 'InStock'),'itemCondition':'https://schema.org/'+('NewCondition' if u['condition']=='new' else 'UsedCondition')}
    breadcrumb={'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Shop RVs','item':config['origin']+'/'},{'@type':'ListItem','position':2,'name':t.TYPE_NAMES[u['type']],'item':config['origin']+'/'+t.TYPE_PATHS[u['type']]+'/'},{'@type':'ListItem','position':3,'name':name,'item':canonical}]}
    return t.document(content,name+' | '+u['stock']+' | MHSRV',f'Explore the {name}: photos, specifications, floorplan resources and pricing. Stock {u["stock"]} in {u["city"]}, {u["state"]}.','units/'+quote(u['stock'],safe='')+'.html',config,'../',body_class='detail-page',schema=[product,breadcrumb])
